static string parseJsonString(const string& line) {
    size_t pos = line.find('"');
    if (pos == string::npos) throw runtime_error("Missing JSON string");
    ++pos;

    string out;
    while (pos < line.size()) {
        char c = line[pos++];
        if (c == '"') return out;
        if (c != '\\') {
            out += c;
            continue;
        }
        if (pos >= line.size()) throw runtime_error("Invalid escape");
        char e = line[pos++];
        switch (e) {
            case '"': out += '"'; break;
            case '\\': out += '\\'; break;
            case '/': out += '/'; break;
            case 'b': out += '\b'; break;
            case 'f': out += '\f'; break;
            case 'n': out += '\n'; break;
            case 'r': out += '\r'; break;
            case 't': out += '\t'; break;
            case 'u':
                if (pos + 4 > line.size()) throw runtime_error("Invalid unicode escape");
                {
                    unsigned code = 0;
                    for (int i = 0; i < 4; ++i) {
                        char h = line[pos++];
                        code <<= 4;
                        if (h >= '0' && h <= '9') code += h - '0';
                        else if (h >= 'a' && h <= 'f') code += h - 'a' + 10;
                        else if (h >= 'A' && h <= 'F') code += h - 'A' + 10;
                        else throw runtime_error("Invalid unicode escape");
                    }
                    out += char(code);
                }
                break;
            default:
                throw runtime_error("Invalid escape");
        }
    }
    throw runtime_error("Unterminated string");
}

static string jsonQuote(const string& s) {
    ostringstream out;
    out << '"';
    for (unsigned char c : s) {
        switch (c) {
            case '"': out << "\\\""; break;
            case '\\': out << "\\\\"; break;
            case '\b': out << "\\b"; break;
            case '\f': out << "\\f"; break;
            case '\n': out << "\\n"; break;
            case '\r': out << "\\r"; break;
            case '\t': out << "\\t"; break;
            default:
