    static String parseJsonString(String line) {
        int i = line.indexOf('"');
        if (i < 0) throw new IllegalArgumentException("Missing JSON string");
        StringBuilder s = new StringBuilder();
        i++;
        while (i < line.length()) {
            char c = line.charAt(i++);
            if (c == '"') return s.toString();
            if (c != '\\') {
                s.append(c);
                continue;
            }
            if (i >= line.length()) throw new IllegalArgumentException("Invalid escape");
            char e = line.charAt(i++);
            switch (e) {
                case '"': s.append('"'); break;
                case '\\': s.append('\\'); break;
                case '/': s.append('/'); break;
                case 'b': s.append('\b'); break;
                case 'f': s.append('\f'); break;
                case 'n': s.append('\n'); break;
                case 'r': s.append('\r'); break;
                case 't': s.append('\t'); break;
                case 'u':
                    if (i + 4 > line.length()) throw new IllegalArgumentException("Invalid unicode escape");
                    int code = Integer.parseInt(line.substring(i, i + 4), 16);
                    s.append((char) code);
                    i += 4;
                    break;
                default:
                    throw new IllegalArgumentException("Invalid escape");
            }
        }
        throw new IllegalArgumentException("Unterminated string");
    }

